  Sum((([MedicationRequest: &quot;Potentially Harmful Antiinfectives for Older Adults&quot;]).moreThanOneOrder()) AntiInfectives
      let DaysSupply: AntiInfectives.MedicationRequestPeriodInDays()
      return all DaysSupply
